import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import '../styles/theme.css';
import './MainLayout.css';

const HomeIcon = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>
    <polyline points="9 22 9 12 15 12 15 22"/>
  </svg>
);
const WriteIcon = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M12 20h9"/>
    <path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/>
  </svg>
);
const GroupIcon = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/>
    <circle cx="9" cy="7" r="4"/>
    <path d="M23 21v-2a4 4 0 0 0-3-3.87"/>
    <path d="M16 3.13a4 4 0 0 1 0 7.75"/>
  </svg>
);
const ProfileIcon = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/>
    <circle cx="12" cy="7" r="4"/>
  </svg>
);
const SearchIcon = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="11" cy="11" r="8"/>
    <line x1="21" y1="21" x2="16.65" y2="16.65"/>
  </svg>
);
const BellIcon = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/>
    <path d="M13.73 21a2 2 0 0 1-3.46 0"/>
  </svg>
);
const PlusIcon = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
    <line x1="12" y1="5" x2="12" y2="19"/>
    <line x1="5" y1="12" x2="19" y2="12"/>
  </svg>
);

const NAV_ITEMS = [
  { path: '/',          label: '홈',      Icon: HomeIcon },
  { path: '/ai-write', label: 'AI글쓰기', Icon: WriteIcon },
  { path: '/community',label: '독서모임', Icon: GroupIcon },
  { path: '/profile',  label: '마이',     Icon: ProfileIcon },
];

export default function MainLayout({ children }) {
  const location = useLocation();
  const navigate = useNavigate();

  const isChatPage = location.pathname.startsWith('/community/');

  return (
    <div className="app-shell">
      {/* Top Header */}
      <header className="top-header">
        <span className="header-logo">READLY</span>
        <div className="header-actions">
          <button className="icon-btn" aria-label="추가"><PlusIcon /></button>
          <button className="icon-btn" aria-label="검색"><SearchIcon /></button>
          <button className="icon-btn notification-btn" aria-label="알림">
            <BellIcon />
            <span className="notification-dot" />
          </button>
        </div>
      </header>

      {/* Page Content */}
      <main className={`main-content${isChatPage ? ' no-padding' : ''}`}>
        {children}
      </main>

      {/* Bottom Navigation */}
      {!isChatPage && (
        <nav className="bottom-nav">
          {NAV_ITEMS.map(({ path, label, Icon }) => {
            const active = location.pathname === path ||
              (path !== '/' && location.pathname.startsWith(path));
            return (
              <button
                key={path}
                className={`bottom-nav-item${active ? ' active' : ''}`}
                onClick={() => navigate(path)}
              >
                <Icon />
                <span>{label}</span>
              </button>
            );
          })}
        </nav>
      )}
    </div>
  );
}
